UPDATE public.data_sources
SET description = 'Демографические показатели муниципальных образований верхнего уровня России за 2010–2023 годы: население, рождаемость, смертность, миграционный прирост и общие коэффициенты. Карточка набора указывает 2 284 муниципалитета из 78 регионов, 31 947 наблюдений и 14 атрибутов.',
    coverage = '2 284 муниципалитета верхнего уровня из 78 регионов; наличие и полнота данных по ХМАО — Югре и 22 муниципалитетам проекта не проверены.',
    notes = 'По открытой карточке набора на 30.10.2026 указаны обновление 03.08.2026, период 2010–2023, 2 284 муниципалитета из 78 регионов, 31 947 наблюдений, 14 атрибутов, CSV/XLSX, CSV UTF-8 с разделителем ;, CC BY 4.0. Поисковый сниппет той же карточки показывает 23.06.2024 и статус «Не обновляется» — метаданные в поисковом индексе расходятся с открытой страницей. Гармонизирована административная сетка; численность населения пересчитана методом демографического баланса от переписи 2010 года. Наличие ХМАО — Югры, ОКТМО и конкретных муниципалитетов необходимо проверить по фактической выгрузке. Числовые наблюдения не импортированы.',
    last_checked_at = now(),
